115	async fn open_sqlite(path: &Path) -> anyhow::Result<SqlitePool> {
116	    let options = SqliteConnectOptions::new()
117	        .filename(path)
118	        .create_if_missing(true)
119	        .journal_mode(SqliteJournalMode::Wal)
120	        .synchronous(SqliteSynchronous::Normal)
121	        .busy_timeout(Duration::from_secs(5))
122	        .log_statements(LevelFilter::Off);
123	    let pool = SqlitePoolOptions::new()
124	        .max_connections(5)
125	        .connect_with(options)
126	        .await?;
127	    MIGRATOR.run(&pool).await?;
128	    Ok(pool)
129	}
