33	        let mut tx = self.pool.begin().await?;
34	
35	        sqlx::query(
36	            r#"
37	DELETE FROM stage1_outputs
38	            "#,
39	        )
40	        .execute(&mut *tx)
41	        .await?;
42	
43	        sqlx::query(
44	            r#"
45	DELETE FROM jobs
46	WHERE kind = ? OR kind = ?
47	            "#,
48	        )
49	        .bind(JOB_KIND_MEMORY_STAGE1)
50	        .bind(JOB_KIND_MEMORY_CONSOLIDATE_GLOBAL)
51	        .execute(&mut *tx)
52	        .await?;
53	
54	        tx.commit().await?;
55	        Ok(())
