4	/// Returns the path to the Codex configuration directory, which can be
5	/// specified by the `CODEX_HOME` environment variable. If not set, defaults to
6	/// `~/.codex`.
7	///
8	/// - If `CODEX_HOME` is set, the value must exist and be a directory. The
9	///   value will be canonicalized and this function will Err otherwise.
10	/// - If `CODEX_HOME` is not set, this function does not verify that the
11	///   directory exists.
12	pub fn find_codex_home() -> std::io::Result<PathBuf> {
13	    let codex_home_env = std::env::var("CODEX_HOME")
14	        .ok()
15	        .filter(|val| !val.is_empty());
16	    find_codex_home_from_env(codex_home_env.as_deref())
17	}
18	
19	fn find_codex_home_from_env(codex_home_env: Option<&str>) -> std::io::Result<PathBuf> {
20	    // Honor the `CODEX_HOME` environment variable when it is set to allow users
21	    // (and tests) to override the default location.
22	    match codex_home_env {
23	        Some(val) => {
24	            let path = PathBuf::from(val);
25	            let metadata = std::fs::metadata(&path).map_err(|err| match err.kind() {
26	                std::io::ErrorKind::NotFound => std::io::Error::new(
27	                    std::io::ErrorKind::NotFound,
28	                    format!("CODEX_HOME points to {val:?}, but that path does not exist"),
29	                ),
30	                _ => std::io::Error::new(
31	                    err.kind(),
32	                    format!("failed to read CODEX_HOME {val:?}: {err}"),
33	                ),
34	            })?;
35	
36	            if !metadata.is_dir() {
37	                Err(std::io::Error::new(
38	                    std::io::ErrorKind::InvalidInput,
39	                    format!("CODEX_HOME points to {val:?}, but that path is not a directory"),
40	                ))
41	            } else {
42	                path.canonicalize().map_err(|err| {
43	                    std::io::Error::new(
44	                        err.kind(),
45	                        format!("failed to canonicalize CODEX_HOME {val:?}: {err}"),
46	                    )
47	                })
48	            }
49	        }
50	        None => {
51	            let mut p = home_dir().ok_or_else(|| {
52	                std::io::Error::new(
53	                    std::io::ErrorKind::NotFound,
54	                    "Could not find home directory",
55	                )
56	            })?;
57	            p.push(".codex");
58	            Ok(p)
59	        }
60	    }
